package cn.workbench;

import java.util.*;
import org.springframework.stereotype.Service;
import static cn.workbench.Records.map;

@Service public class WorkItemService {
 final Records records; final Store db; final Policy policy; final Writes writes;
 public WorkItemService(Records records,Store db,Policy policy,Writes writes){this.records=records;this.db=db;this.policy=policy;this.writes=writes;}
 boolean manager(Policy.Actor a,Map<String,Object> task,int company,int dept){return a.delegationId()==null&&(a.globalAdmin()||a.role().equals("GROUP_LEADER")||a.leader()&&Objects.equals(a.company(),Jsons.integer(task.get("companyId")))||a.departmentHead()&&Objects.equals(a.company(),company)&&Objects.equals(a.dept(),dept));}
 boolean visible(Policy.Actor a,Map<String,Object> task,Map<String,Object> item){return manager(a,task,TaskService.integer(item,"companyId"),TaskService.integer(item,"deptId"))||Objects.equals(a.company(),TaskService.integer(item,"companyId"))&&Objects.equals(a.dept(),TaskService.integer(item,"deptId"))&&a.uid()==TaskService.number(item,"ownerId");}
 void mutable(Map<String,Object> task){if(Set.of("COMPLETED","CANCELLED","PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(task.get("status")))throw ApiException.conflict();}
 void validOwner(long uid,int company,int dept){var user=db.user(uid);if(user==null||!Boolean.TRUE.equals(user.get("enabled"))||db.scopes(uid).stream().noneMatch(s->s.get("companyId")!=null&&s.get("deptId")!=null&&Jsons.integer(s.get("companyId"))==company&&Jsons.integer(s.get("deptId"))==dept))throw TaskService.invalid("负责人须属于所选部门");}
 Map<String,Object> view(Policy.Actor a,Map<String,Object> task,Map<String,Object> item){var out=new LinkedHashMap<>(item);var user=db.user(TaskService.number(item,"ownerId"));out.put("ownerName",user==null?"未知用户":user.get("name"));out.put("deptName",records.get(TaskService.number(item,"deptId")).get("name"));boolean open=!Set.of("DRAFT","COMPLETED","CANCELLED","PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(task.get("status"));out.put("allowedActions",open&&(manager(a,task,TaskService.integer(item,"companyId"),TaskService.integer(item,"deptId"))||a.uid()==TaskService.number(item,"ownerId"))?List.of("update"):List.of());return out;}
 public Map<String,Object> create(Policy.Actor a,long taskId,Map<String,Object> body){policy.task(a,taskId);var task=records.lock(taskId);mutable(task);int dept=TaskService.integer(body,"deptId");var sub=records.children(taskId,"SUB_TASK").stream().filter(s->TaskService.integer(s,"deptId")==dept).findFirst().orElseThrow(ApiException::denied);int company=TaskService.integer(sub,"companyId");if(!manager(a,task,company,dept))throw ApiException.denied();long owner=TaskService.number(body,"ownerId");validOwner(owner,company,dept);String title=TaskService.text(body,"title",300);var deadline=TaskService.future(body,"deadline");var item=records.create("WORK_ITEM",company,dept,taskId,owner,"IN_PROGRESS",map("title",title,"deadline",deadline.toString(),"percent",0,"createdBy",a.uid()));writes.audit(a,"WORK_ITEM_CREATE",TaskService.number(item,"id"));return view(a,task,item);}
 public Map<String,Object> update(Policy.Actor a,long id,Map<String,Object> body){var item=records.get(id);if(!"WORK_ITEM".equals(item.get("kind")))throw ApiException.denied();long taskId=TaskService.number(item,"taskId");policy.task(a,taskId);var task=records.lock(taskId);mutable(task);item=records.lock(id);int company=TaskService.integer(item,"companyId"),dept=TaskService.integer(item,"deptId");boolean manager=manager(a,task,company,dept);if(!visible(a,task,item)||!manager&&a.uid()!=TaskService.number(item,"ownerId")||"DRAFT".equals(task.get("status")))throw ApiException.denied();TaskService.version(item,body);int percent=TaskService.integer(body,"percent");if(percent<0||percent>100)throw TaskService.invalid("进度须介于0至100");if(body.containsKey("title")||body.containsKey("ownerId")||body.containsKey("deadline")){if(!manager)throw ApiException.denied();if(body.containsKey("title"))item.put("title",TaskService.text(body,"title",300));if(body.containsKey("deadline"))item.put("deadline",TaskService.future(body,"deadline").toString());if(body.containsKey("ownerId")){long owner=TaskService.number(body,"ownerId");validOwner(owner,company,dept);item.put("ownerId",owner);}}item.put("percent",percent);item.put("status",percent==100?"COMPLETED":"IN_PROGRESS");records.save(item);writes.audit(a,"WORK_ITEM_UPDATE",id);return view(a,task,item);}
 public List<Map<String,Object>> manageableDepartments(Policy.Actor a,Map<String,Object> task){if(Set.of("COMPLETED","CANCELLED","PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(task.get("status")))return List.of();return records.children(TaskService.number(task,"id"),"SUB_TASK").stream().filter(s->manager(a,task,TaskService.integer(s,"companyId"),TaskService.integer(s,"deptId"))).map(s->map("id",s.get("deptId"),"name",records.get(TaskService.number(s,"deptId")).get("name"))).toList();}
 public List<Map<String,Object>> members(Policy.Actor a,long taskId,int dept){var task=policy.task(a,taskId);var sub=records.children(taskId,"SUB_TASK").stream().filter(s->TaskService.integer(s,"deptId")==dept).findFirst().orElseThrow(ApiException::denied);int company=TaskService.integer(sub,"companyId");if(!manager(a,task,company,dept))throw ApiException.denied();return db.users().stream().filter(u->Boolean.TRUE.equals(u.get("enabled"))&&db.scopes(TaskService.number(u,"id")).stream().anyMatch(s->s.get("companyId")!=null&&s.get("deptId")!=null&&Jsons.integer(s.get("companyId"))==company&&Jsons.integer(s.get("deptId"))==dept)).map(u->map("id",u.get("id"),"name",u.get("name"))).toList();}
 public List<Map<String,Object>> mine(Policy.Actor a){if(a.company()==null||a.dept()==null)return List.of();return records.list("WORK_ITEM",a.company(),a.dept()).stream().filter(item->TaskService.number(item,"ownerId")==a.uid()).map(item->{var task=records.get(TaskService.number(item,"taskId"));if("DRAFT".equals(task.get("status"))||!policy.canSeeTask(a,task))return null;var out=view(a,task,item);out.put("code",task.get("code"));out.put("priority",task.get("priority"));out.put("taskTitle",task.get("title"));return out;}).filter(Objects::nonNull).toList();}
 public List<Map<String,Object>> forTask(Policy.Actor a,Map<String,Object> task){return records.children(TaskService.number(task,"id"),"WORK_ITEM").stream().filter(item->visible(a,task,item)).map(item->view(a,task,item)).toList();}
}
